# This is GridMaster's API interface.
# You should not implement it, or speculate about its implementation
# class GridMaster(object):
#     def canMove(self, direction):
#     def move(self, direction):
#     def isTarget(self):

class Solution:
    def findShortestPath(self, master: 'GridMaster') -> int:
        dirs = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
        opp = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
        grid = {(0, 0): 3 if master.isTarget() else 1}
        target = (0, 0) if grid[(0, 0)] == 3 else None
        stack = [(0, 0)]
        while stack:
            r, c = stack[-1]
            advanced = False
            for d, (dr, dc) in dirs.items():
                nb = (r + dr, c + dc)
                if nb in grid:
                    continue
                if master.canMove(d):
                    master.move(d)
                    grid[nb] = 3 if master.isTarget() else 1
                    if grid[nb] == 3 and target is None:
                        target = nb
                    stack.append(nb)
                    advanced = True
                    break
                grid[nb] = -1
            if not advanced:
                stack.pop()
                if stack:
                    pr, pc = stack[-1]
                    for d, (dr, dc) in dirs.items():
                        if (r + dr, c + dc) == (pr, pc):
                            master.move(d)
                            break
        if target is None:
            return -1
        from collections import deque
        q = deque([(0, 0)])
        dist = {(0, 0): 0}
        while q:
            r, c = q.popleft()
            if (r, c) == target:
                return dist[(r, c)]
            for dr, dc in dirs.values():
                nb = (r + dr, c + dc)
                if grid.get(nb, -1) != -1 and nb not in dist:
                    dist[nb] = dist[(r, c)] + 1
                    q.append(nb)
        return -1

