/**
 * // This is GridMaster's API class.
 * // You should not implement it, or speculate about its implementation
 * class GridMaster {
 *   public:
 *     bool canMove(char direction);
 *     void move(char direction);
 *     bool isTarget();
 * };
 */
class Solution {
    unordered_map<long long, int> grid_;
    long long target_ = LLONG_MIN;
    int dr_[4] = {-1, 1, 0, 0}, dc_[4] = {0, 0, -1, 1};
    char ch_[4] = {'U', 'D', 'L', 'R'};

    long long key(long long r, long long c) { return (r + 500) * 1000 + (c + 500); }

    void mark(GridMaster* m, int r, int c) {
        int st = m->isTarget() ? 3 : 1;
        grid_[key(r, c)] = st;
        if (st == 3) target_ = key(r, c);
    }

    void dfs(GridMaster* m, int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + dr_[i], nc = c + dc_[i];
            if (grid_.count(key(nr, nc))) continue;
            if (m->canMove(ch_[i])) {
                m->move(ch_[i]);
                mark(m, nr, nc);
                dfs(m, nr, nc);
                m->move(ch_[i ^ 1]);
            } else {
                grid_[key(nr, nc)] = -1;
            }
        }
    }

public:
    int findShortestPath(GridMaster* master) {
        mark(master, 0, 0);
        dfs(master, 0, 0);
        if (target_ == LLONG_MIN) return -1;
        queue<pair<int, int>> q;
        q.push({0, 0});
        unordered_map<long long, int> dist;
        dist[key(0, 0)] = 0;
        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();
            if (key(r, c) == target_) return dist[key(r, c)];
            for (int i = 0; i < 4; i++) {
                long long nk = key(r + dr_[i], c + dc_[i]);
                if (grid_.count(nk) && grid_[nk] != -1 && !dist.count(nk)) {
                    dist[nk] = dist[key(r, c)] + 1;
                    q.push({r + dr_[i], c + dc_[i]});
                }
            }
        }
        return -1;
    }
};

