/**
 * // This is GridMaster's API interface.
 * // You should not implement it, or speculate about its implementation
 * interface GridMaster {
 *     boolean canMove(char direction);
 *     void move(char direction);
 *     boolean isTarget();
 * }
 */
class Solution {
    private static final int[] DR = {-1, 1, 0, 0}, DC = {0, 0, -1, 1};
    private static final char[] CH = {'U', 'D', 'L', 'R'};
    private Map<Long, Integer> grid;
    private long target;

    public int findShortestPath(GridMaster master) {
        grid = new HashMap<>();
        target = Long.MIN_VALUE;
        mark(master, 0, 0);
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0});
        while (!stack.isEmpty()) {
            int[] top = stack.peek();
            boolean advanced = false;
            for (int i = 0; i < 4; i++) {
                int nr = top[0] + DR[i], nc = top[1] + DC[i];
                if (grid.containsKey(key(nr, nc))) continue;
                if (master.canMove(CH[i])) {
                    master.move(CH[i]);
                    mark(master, nr, nc);
                    stack.push(new int[]{nr, nc});
                    advanced = true;
                    break;
                } else {
                    grid.put(key(nr, nc), -1);
                }
            }
            if (!advanced) {
                stack.pop();
                if (!stack.isEmpty()) {
                    int[] par = stack.peek();
                    for (int i = 0; i < 4; i++) {
                        if (top[0] + DR[i] == par[0] && top[1] + DC[i] == par[1]) {
                            master.move(CH[i]);
                            break;
                        }
                    }
                }
            }
        }
        if (target == Long.MIN_VALUE) return -1;
        Deque<int[]> q = new ArrayDeque<>();
        Map<Long, Integer> dist = new HashMap<>();
        dist.put(key(0, 0), 0);
        q.add(new int[]{0, 0});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (key(cur[0], cur[1]) == target) return dist.get(key(cur[0], cur[1]));
            for (int i = 0; i < 4; i++) {
                long nk = key(cur[0] + DR[i], cur[1] + DC[i]);
                if (grid.getOrDefault(nk, -1) != -1 && !dist.containsKey(nk)) {
                    dist.put(nk, dist.get(key(cur[0], cur[1])) + 1);
                    q.add(new int[]{cur[0] + DR[i], cur[1] + DC[i]});
                }
            }
        }
        return -1;
    }

    private void mark(GridMaster master, int r, int c) {
        int st = master.isTarget() ? 3 : 1;
        grid.put(key(r, c), st);
        if (st == 3) target = key(r, c);
    }

    private long key(long r, long c) {
        return (r + 500) * 1000 + (c + 500);
    }
};

