 *     this.canMove = function(direction) { ... };
 *     this.move = function(direction) { ... };
 *     this.isTarget = function() { ... };
 * };
 */
var findShortestPath = function(master) {
    const dirs = [['U', -1, 0], ['D', 1, 0], ['L', 0, -1], ['R', 0, 1]];
    const key = (r, c) => (r + 500) * 1000 + (c + 500);
    const grid = new Map();
    let target = -1;
    const mark = (r, c) => {
        const st = master.isTarget() ? 3 : 1;
        grid.set(key(r, c), st);
        if (st === 3 && target === -1) target = key(r, c);
    };
    mark(0, 0);
    const stack = [[0, 0]];
    while (stack.length) {
        const [r, c] = stack[stack.length - 1];
        let advanced = false;
        for (const [d, dr, dc] of dirs) {
            const nk = key(r + dr, c + dc);
            if (grid.has(nk)) continue;
            if (master.canMove(d)) {
                master.move(d);
                mark(r + dr, c + dc);
                stack.push([r + dr, c + dc]);
                advanced = true;
                break;
            } else {
                grid.set(nk, -1);
            }
        }
        if (!advanced) {
            stack.pop();
            if (stack.length) {
                const [pr, pc] = stack[stack.length - 1];
                for (const [d, dr, dc] of dirs) {
                    if (r + dr === pr && c + dc === pc) {
                        master.move(d);
                        break;
                    }
                }
            }
        }
    }
    if (target === -1) return -1;
    const q = [[0, 0]];
    const dist = new Map([[key(0, 0), 0]]);
    for (let h = 0; h < q.length; h++) {
        const [r, c] = q[h];
        if (key(r, c) === target) return dist.get(key(r, c));
        for (const [, dr, dc] of dirs) {
            const nk = key(r + dr, c + dc);
            if ((grid.get(nk) ?? -1) !== -1 && !dist.has(nk)) {
                dist.set(nk, dist.get(key(r, c)) + 1);
                q.push([r + dr, c + dc]);
            }
        }
    }
    return -1;
};
